    a = a[2:] + [l for l in open(a[1]).read().split('\n') if l.strip()]
elif a[0] == '-G':
    # a python file whose CMDS list is the commands
    ns = {}
    exec(open(a[1]).read(), ns)
    a = a[2:] + ns['CMDS']
else: break

