env = dict(os.environ)
env['MINE'] = MINE
os.makedirs(B + '/logs', exist_ok=True)
jobs = []
for f in sorted(glob.glob(B + '/elec/cases_*.txt')):
    jobs.append(('elec_' + os.path.basename(f), ['python3', B + '/elec/batch.py', f], B + '/elec'))
for f in sorted(glob.glob(B + '/fills/cases*.txt')):
    jobs.append(('fills_' + os.path.basename(f), ['python3', B + '/fills/batch.py', f], B + '/fills'))
