    jobs.append(('phasing_' + os.path.basename(f), ['python3', B + '/phasing/suite.py', f], B + '/phasing'))
for f in sorted(glob.glob(B + '/text/*.txt')):
    jobs.append(('text_' + os.path.basename(f), ['python3', B + '/text/batch.py', f], B + '/text'))
